BEGIN;

UPDATE `invoice_detail`, `project_reservation_service_detail` 
	SET `invoice_detail`.`source` = 9, `invoice_detail`.`source_id` =  `project_reservation_service_detail`.`invoice_detail`
	WHERE `project_reservation_service_detail`.`invoice_detail` IS NOT NULL
	AND `project_reservation_service_detail`.`invoice_detail` = `invoice_detail`.`id`;

ALTER TABLE `project_reservation_service_detail` DROP FOREIGN KEY `FK_PROJECT_RESERVATION_SERVICE_DETAIL_INVOICE_DETAIL`;
ALTER TABLE `project_reservation_service_detail` DROP KEY `IDX_PROJECT_RESERVATION_SERVICE_DETAIL_INVOICE_DETAIL`;
ALTER TABLE `project_reservation_service_detail` DROP `invoice_detail`;

CREATE TABLE `contract_clause` (
  `id` int(4) NOT NULL auto_increment COMMENT 'Identificador unico',
  `domain` int(4) NOT NULL COMMENT 'Identificador del Dominio',
  `contract` int(4) default NULL COMMENT 'Identificador del Contrato',
  `line` smallint(2) default '1' COMMENT 'Numero de linea de la Clausula del Contrato',
  `name` varchar(64) collate latin1_spanish_ci NOT NULL default '' COMMENT 'Titulo de la Clausula de Contrato',
  `description` text collate latin1_spanish_ci NOT NULL COMMENT 'Descripcion de la Clausula de Contrato',
  `general` tinyint(1) default '0' COMMENT 'Indica si la Clausula es particular o general',
  PRIMARY KEY  (`id`),
  KEY `IDX_CONTRACT_CLAUSE_CONTRACT` (`contract`),
  KEY `IDX_CONTRACT_CLAUSE_DOMAIN` (`domain`),
  CONSTRAINT `FK_CONTRACT_CLAUSE_DOMAIN` FOREIGN KEY (`domain`) REFERENCES `domain` (`id`),
  CONSTRAINT `FK_CONTRACT_CLAUSE_CONTRACT` FOREIGN KEY (`contract`) REFERENCES `contract` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_spanish_ci COMMENT='Clausulas de contrato';

ALTER TABLE `purchase` ADD `purchase_reference` varchar(32) collate latin1_spanish_ci default NULL COMMENT 'Codigo de referencia del Pedido de Compra' AFTER `number`;


DELETE FROM `geozone_irpf_handicap`;
DELETE FROM `geozone_irpf_descendant`;
DELETE FROM `geozone_irpf`;

 
 

  
  


UPDATE `db_version` SET `version_number` = '7.27.0';

COMMIT;
